import os
import subprocess
import google.generativeai as genai

def main():
    # 1. Configure the Gemini API
    api_key = os.environ.get("GEMINI_API_KEY")
    if not api_key:
        print("Error: GEMINI_API_KEY not found.")
        return
        
    genai.configure(api_key=api_key)
    # Gemini 1.5 Flash is ideal for fast, cost-effective code tasks
    model = genai.GenerativeModel('gemini-3.8-flash')

    # 2. Read the Git diff generated by the GitHub Action
    try:
        with open("pr_diff.txt", "r") as f:
            diff_text = f.read()
    except FileNotFoundError:
        print("No diff file found.")
        return

    if not diff_text.strip():
        print("Diff is empty. Nothing to review.")
        return

    # 3. Create the prompt for Gemini
    prompt = f"""
    You are an expert senior software engineer reviewing a pull request for a trading application. 
    Analyze the following Git diff. 
    
    Focus on:
    - Logic errors or edge cases in financial calculations/trading logic
    - Security vulnerabilities
    - Performance bottlenecks
    - Code readability
    
    Provide a concise summary of the changes, followed by bullet points of specific, actionable feedback.
    If the code looks perfect, say so. Do not nitpick minor formatting.

    Here is the diff:
    ```diff
    {diff_text}
    ```
    """

    # 4. Generate the review
    print("Sending diff to Gemini...")
    response = model.generate_content(prompt)
    review_comment = response.text

    # 5. Post the review as a comment on the GitHub PR using the GitHub CLI
    pr_number = os.environ["PR_NUMBER"]
    command = ["gh", "pr", "comment", pr_number, "--body", review_comment]
    
    print("Posting review to GitHub...")
    subprocess.run(command, check=True)

if __name__ == "__main__":
    main()
